$mod = 1000003;

function modpow($base, $exp, $mod) {
    $result = 1;
    $base = $base % $mod;
    while ($exp > 0) {
        if ($exp % 2 == 1) {
            $result = ($result * $base) % $mod;
        }
        $exp = intdiv($exp, 2);
        $base = ($base * $base) % $mod;
    }
    return $result;
}

function modinv($a, $mod) {
    return modpow($a, $mod - 2, $mod);
}

